import java.io.*;import java.util.*;class Result {public static String highestValuePalindrome(String s, int n, int k) {char[] arr = s.toCharArray();boolean[] changed = new boolean[n];int changesNeeded = 0;for (int i = 0; i < n / 2; i++) {if (arr[i] != arr[n - 1 - i]) {changesNeeded++;}}if (changesNeeded > k) return "-1";int remainingK = k;for (int i = 0; i < n / 2; i++) {if (arr[i] != arr[n - 1 - i]) {if (remainingK > changesNeeded && (arr[i] != '9' && arr[n - 1 - i] != '9')) {arr[i] = '9';arr[n - 1 - i] = '9';remainingK -= 2;} else {char maxChar = (char) Math.max(arr[i], arr[n - 1 - i]);arr[i] = maxChar;arr[n - 1 - i] = maxChar;remainingK -= 1;}changesNeeded--;} else {if (remainingK >= changesNeeded + 2 && arr[i] != '9') {arr[i] = '9';arr[n - 1 - i] = '9';remainingK -= 2;}}}if (n % 2 != 0 && remainingK > 0) {arr[n / 2] = '9';}return new String(arr);}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int n = Integer.parseInt(firstMultipleInput[0]);int k = Integer.parseInt(firstMultipleInput[1]);String s = bufferedReader.readLine();String result = Result.highestValuePalindrome(s, n, k);bufferedWriter.write(result);bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}